import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Хранилище и эскроу","description":"","frontmatter":{"pageId":"developers/storage","contentRevision":5},"headers":[],"relativePath":"ru/developers/storage.md","filePath":"ru/developers/storage.md"}'),l={name:"ru/developers/storage.md"};function i(s,e,d,n,p,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="хранилище-и-эскроу" tabindex="-1">Хранилище и эскроу <a class="header-anchor" href="#хранилище-и-эскроу" aria-label="Permalink to &quot;Хранилище и эскроу&quot;">​</a></h1><p>Применимость: Rimlink 0.9.2 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Изменение схемы — EF Core migration и schema test. Команда: dotnet ef migrations add &lt;Name&gt; --project src/Rimlink.Server (без -nologo). Миграции применяются при запуске.</p><p>SaveFiles единственный знает имена: &lt;n&gt;.rws.zst — полный сейв, &lt;n&gt;.d&lt;k&gt;.zst — delta к base-&lt;k&gt;.rws.zst. Size/Sha256 описывают полный контент даже при delta на диске. Только OpenCurrent гарантирует восстановление актуальной версии; нельзя предполагать наличие полного файла для любой старой записи. Проверяй hash до доверия существующему файлу.</p><p>Эскроу хранит отправленные предметы/пешек/серебро до исхода, возврат идёт почтой. Состояние live меняется под LiveStateLock с чтением строки внутри lock. Backup держит PerStoreLock и save-storage.lock при снимке БД и упаковке сейвов.</p><h3 id="поколение-колонии-и-эпоха-записи" tabindex="-1">Поколение колонии и эпоха записи <a class="header-anchor" href="#поколение-колонии-и-эпоха-записи" aria-label="Permalink to &quot;Поколение колонии и эпоха записи&quot;">​</a></h3><p><code>SaveGeneration</code> меняется при reset: старый локальный сейв не должен стать первой версией новой колонии. <code>SaveWriteEpoch</code> меняется при административном rollback внутри того же поколения: прежняя сессия/исходящие операции не должны перезаписать выбранную администратором временную линию. Номер версии сейва — отдельный последовательный идентификатор, не один из этих счётчиков.</p><p>Upload сверяет generation/epoch заголовка, recovery proof и эпоху начатой сессии; несовпадение даёт SaveGenerationMismatch или SaveWriteEpochMismatch. После rollback клиент должен получить актуальные authority и снимок, а не повторять устаревший outbox с переписанными метаданными. Проверяй тестом: начни старый upload, выполни rollback, затем продолжи upload — он обязан быть отвергнут без изменения текущего сейва.</p><h2 id="storage-repair" tabindex="-1">Порядок исследования повреждённого сейва <a class="header-anchor" href="#storage-repair" aria-label="Permalink to &quot;Порядок исследования повреждённого сейва {#storage-repair}&quot;">​</a></h2><p>Сначала зафиксируй строки версии и неизменяемую копию файлов, затем используй SaveFiles для открытия полного содержимого. Не выводи путь старой версии из одного номера: на диске может быть delta. Size/Sha256 описывают полную распакованную версию, не размер delta.</p><p>Пара full+delta может означать прерванную перестройку. Сверь сырые данные и metadata до удаления «лишнего» файла. Совпадение имени не делает hash корректным. Backup/restore держат shared storage lock; обход блокировки ручным SQL/копированием делает картину недостоверной.</p><p>Изменение схемы — migration и schema regression test. Исправление данных должно сначала воспроизводиться на копии, с явным списком потерянных/восстановленных версий, а не обещанием полного восстановления.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Не удаляй lock-файл. Полный файл со spare delta может быть незавершённым rebuild: сначала сверить raw содержимое и metadata. zstd prefix и input не должны быть одним массивом. Не коммить *.db и каталоги данных.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./../admins/backup-recovery">Резервные копии и восстановление</a></li><li><a href="./protocol">Протокол и идемпотентность</a></li><li><a href="./testing">Тестирование и приёмка</a></li></ul>',17)])])}const m=a(l,[["render",i]]);export{u as __pageData,m as default};
